<template><view class="verify-page"><view class="nav"><text @tap="back">‹</text><text>安全验证</text><view/></view><view class="body"><view class="phone-icon">✦</view><text class="title">安全验证码</text><text class="copy">验证码将发送至绑定手机号 123****2333</text><view class="code-boxes"><input v-for="(_,i) in 6" :key="i" :value="code[i]||''" maxlength="1" type="number" @input="inputCode($event,i)"/></view><text class="resend" @tap="send">{{countdown?`${countdown}s 后重发`:'获取验证码'}}</text><button :disabled="code.length!==6" @tap="confirm">确认添加</button></view><view v-if="success" class="mask"><view class="success"><view>✓</view><b>添加成功！</b><text>银行卡已添加至你的账户</text></view></view></view></template>
<script setup>import{onBeforeUnmount,onMounted,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{enforcePortal}from'../../core/route-guard';import{addBankCard}from'../../services/wallet';const bank=ref('工商银行'),cardNo=ref(''),code=ref(''),countdown=ref(0),success=ref(false);let timer;onLoad(o=>{bank.value=o?.bank||bank.value;cardNo.value=o?.cardNo||''});onMounted(()=>enforcePortal('agent'));onBeforeUnmount(()=>clearInterval(timer));function back(){uni.navigateBack()}function inputCode(e,i){const next=(e.detail.value||'').replace(/\D/g,'');const chars=code.value.split('');chars[i]=next.slice(-1);code.value=chars.join('').slice(0,6)}function send(){if(countdown.value)return;countdown.value=60;timer=setInterval(()=>{countdown.value--;if(!countdown.value)clearInterval(timer)},1000);uni.showToast({title:'验证码已发送（演示码：123456）',icon:'none'})}function confirm(){if(code.value!=='123456'){uni.showToast({title:'验证码错误',icon:'none'});return}addBankCard({bank:bank.value,cardNo:cardNo.value});success.value=true;setTimeout(()=>uni.redirectTo({url:'/pages/agent/bank-cards'}),1200)}</script>
<style lang="scss" scoped>.verify-page{min-height:100vh;background:#f7f8fc;color:#28334c}.nav{display:flex;justify-content:space-between;align-items:center;height:calc(102rpx + env(safe-area-inset-top));padding:env(safe-area-inset-top) 32rpx 0;background:#fff;box-sizing:border-box;font-size:30rpx;font-weight:720}.nav text:first-child{width:60rpx;color:#5966f3;font-size:60rpx;line-height:1}.nav view{width:60rpx}.body{padding:98rpx 48rpx;text-align:center}.phone-icon{display:flex;align-items:center;justify-content:center;width:90rpx;height:90rpx;margin:auto;border-radius:29rpx;background:#e6e8ff;color:#5966f3;font-size:43rpx}.title,.copy,.resend{display:block}.title{margin-top:31rpx;font-size:37rpx;font-weight:750}.copy{margin-top:14rpx;color:#9099a9;font-size:22rpx}.code-boxes{display:flex;justify-content:center;gap:13rpx;margin-top:53rpx}.code-boxes input{width:65rpx;height:70rpx;border:1rpx solid #d5dbe7;border-radius:12rpx;background:#fff;text-align:center;font-size:31rpx;box-sizing:border-box}.resend{margin-top:27rpx;color:#5966f3;font-size:22rpx}.body button{width:100%;margin-top:45rpx;border:0;border-radius:16rpx;background:#5966f3;color:#fff;font-size:27rpx;line-height:88rpx}.body button[disabled]{background:#c6cbd8}.body button::after{border:0}.mask{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;background:rgba(24,31,51,.4)}.success{display:flex;flex-direction:column;align-items:center;width:510rpx;padding:55rpx 30rpx;border-radius:26rpx;background:#fff}.success view{display:flex;align-items:center;justify-content:center;width:74rpx;height:74rpx;border-radius:50%;background:#e1f8e8;color:#24a159;font-size:39rpx}.success b{margin-top:23rpx;font-size:31rpx}.success text{margin-top:12rpx;color:#94a0b0;font-size:22rpx}</style>
